async function api(path: string, options?: RequestInit) {
  const response = await fetch(`/api/dashboard/${path}`, { credentials: "same-origin", ...options, headers: { "Content-Type": "application/json", ...(options?.headers || {}) } });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw Object.assign(new Error(body.error || "Anfrage fehlgeschlagen"), { status: response.status, code: body.code });
  return body;
}

// Every dashboard view assumes these arrays exist and maps/reduces over
// them directly without guards. A malformed or truncated response (a
// backend bug, a transient proxy error) would otherwise hard-crash the
// whole render tree instead of just showing empty sections.
const overviewArrayFields = ["clients", "opportunities", "projects", "contentRequests", "portalMemberships", "tasks", "quotes", "invoices", "founderTransactions", "aiJobs", "audit", "approvals", "profiles"] as const;
function normalizeOverview(raw: any): Data {
  const normalized: any = { ...raw };
  for (const field of overviewArrayFields) {
    if (!Array.isArray(normalized[field])) normalized[field] = [];
  }
  if (!normalized.profile || typeof normalized.profile !== "object") {
    throw new Error("Unvollständige Antwort vom Server – bitte neu laden.");
  }
  if (!normalized.settings || typeof normalized.settings !== "object") normalized.settings = {};
  const collaboration = normalized.projectCollaboration || {};
  normalized.projectCollaboration = { available: collaboration.available === true, briefings: Array.isArray(collaboration.briefings) ? collaboration.briefings : [], messages: Array.isArray(collaboration.messages) ? collaboration.messages : [], deliverables: Array.isArray(collaboration.deliverables) ? collaboration.deliverables : [], versions: Array.isArray(collaboration.versions) ? collaboration.versions : [], reviews: Array.isArray(collaboration.reviews) ? collaboration.reviews : [], revisions: Array.isArray(collaboration.revisions) ? collaboration.revisions : [], campaigns: Array.isArray(collaboration.campaigns) ? collaboration.campaigns : [] };
  return normalized as Data;
}

const money = (value: unknown) => new Intl.NumberFormat("de-CH", { style: "currency", currency: "CHF" }).format(Number(value || 0));
const shortDate = (value: unknown) => value ? new Intl.DateTimeFormat("de-CH", { day: "2-digit", month: "2-digit", year: "numeric" }).format(new Date(String(value))) : "–";
const company = (row: Row) => Array.isArray(row.client) ? row.client[0]?.company_name : row.client?.company_name;
const relationField = (row: Row, relation: string, field: string) => Array.isArray(row[relation]) ? row[relation][0]?.[field] : row[relation]?.[field];
const dateValue = (value: unknown) => value ? String(value).slice(0, 10) : "";
const dateTimeValue = (value: unknown) => {
  if (!value) return "";
  const date = new Date(String(value));
  return new Date(date.getTime() - date.getTimezoneOffset() * 60_000).toISOString().slice(0, 16);
};
